cssRules.selector:
/* Canonical opt-in visual recipes. Import after generated tokens.css.
   Layout ownership, route logic, tray positioning and focus management stay with components. */
@font-face

/* Compact icon navigation is distinct from quiet content text: a bounded
    tonal circle makes paging discoverable without adding a rest-state border. */
 .cu-action[data-format="compact"][data-variant="quiet"]:hover:not(:disabled):not([aria-disabled="true"])

/* Shared application chrome: the lab and stories render headerBar/bottomBar.
   Hosts position bars; these recipes own their internal visual composition. */
.cu-header

/* Story-host specialization: intrinsic task panels, read-only records and dialogs.
   Shared colors, actions, navigation and feedback remain owned by theme/. */
*

